package com.healthcompanion.ai; import com.healthcompanion.domain.*; import com.healthcompanion.repository.*; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.web.server.ResponseStatusException;
@Service public class DocumentRagService {private final MedicalDocumentRepository documents;private final DocumentChunkRepository chunks;private final EmbeddingGateway embeddings;private final PgVectorStore vectors;public DocumentRagService(MedicalDocumentRepository d,DocumentChunkRepository c,EmbeddingGateway e,PgVectorStore v){documents=d;chunks=c;embeddings=e;vectors=v;}public Result retrieve(long patientId,long documentId,String question){var d=documents.findByIdAndPatientId(documentId,patientId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));var ids=vectors.nearestDocumentChunks(documentId,embeddings.embed(question),embeddings.profile(),4);var byId=new HashMap<Long,DocumentChunk>();chunks.findByDocumentIdOrderByChunkIndex(documentId).forEach(c->byId.put(c.id,c));var selected=ids.stream().map(byId::get).filter(Objects::nonNull).toList();return new Result(d,selected);}public record Result(MedicalDocument document,List<DocumentChunk> chunks){public String context(){return chunks.stream().map(c->c.content).reduce("",(a,b)->a+"\n"+b);}}}
